/*
 * A067511  Powers of 7 with digit sum divisible by 7.
 * https://oeis.org/A067511
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, easy, nonn
 * Formula:   not stated
 * Range:     u8 n <= 1, u16 n <= 2, u32 n <= 5, u64 n <= 5, u128 n <= 9,
 *            big any n
 * Helpers:   append_candidate, digit_sum, ensure_capacity, mul_small
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Compute the OEIS sequence A067511: Powers of 7 with digit sum divisible by 7. */
/* The sequence is generated by iterating 7^k, computing the sum of its decimal digits, */
/* and selecting those where the sum is a multiple of 7.  The generated values are */
/* stored in a static cache so that subsequent calls to different indices are fast. */

#include <stddef.h>
#include "../utils/mul_small.h"
#include "../utils/digit_sum.h"
#include "../utils/append_candidate.h"
#include "../utils/ensure_capacity.h"

seq_t a(idx_t n)
{
    /* Static cache of found terms and state for continuing the generation. */
    static seq_t *cache   = NULL;   /* array of sequence values */
    static size_t cache_len = 0;    /* number of stored terms */
    static size_t cache_cap = 0;    /* capacity of cache array */

    static seq_t cur_pow = 0;       /* current 7^exp value */
    static idx_t cur_exp = 0;       /* current exponent (matching cur_pow) */

    /* Initialise on first call. */
    if (cache == NULL) {
        /* Allocate initial cache capacity. */
        cache_cap = 16;
        cache = (seq_t *)malloc(sizeof(seq_t) * cache_cap);
        /* Start with 7^1. */
        cur_pow = 7;
        cur_exp = 1;
        /* Compute digit sum of 7^1 and store if divisible by 7. */
        seq_t ds = digit_sum(cur_pow);
        if (ds % (seq_t)7 == 0) {
            append_candidate(&cache, &cache_len, &cache_cap, cur_pow);
        }
    }

    /* Extend the cached sequence until it contains at least n terms. */
    while (cache_len < (size_t)n) {
        /* Compute the next power of 7. */
        cur_pow = mul_small(cur_pow, 7);
        ++cur_exp;
        seq_t ds = digit_sum(cur_pow);
        if (ds % (seq_t)7 == 0) {
            append_candidate(&cache, &cache_len, &cache_cap, cur_pow);
        }
    }

    /* Return the nth term (1‑based). */
    return cache[n - 1];
}
